import * as THREE from 'three';
// Shared authored layout: meshes, collisions and seated anchors cannot drift apart.
export const SCHOOL_DESKS=Object.freeze({...Object.fromEntries(['korean','english','socialStudies'].map(roomId=>[roomId,[[-2.7,-.65],[2.7,-.65],[-2.7,1.85],[2.7,1.85]].map(([x,z],i)=>({id:roomId+'.student-desk.'+i,roomId,i,x,z,width:1.75,depth:1.05,chairZ:z+1.50}))])),art:[[-2.8,.25],[2.8,.25]].map(([x,z],i)=>({id:`art.student-desk.${i}`,roomId:'art',i,x,z,width:2.4,depth:1.2,chairZ:z+1.52})),math:[[-2.7,-.65],[2.7,-.65],[-2.7,1.85],[2.7,1.85]].map(([x,z],i)=>({id:`math.student-desk.${i}`,roomId:'math',i,x,z,width:1.75,depth:1.05,chairZ:z+1.50}))});
export const schoolFurnitureObstacles=id=>(SCHOOL_DESKS[id]??[]).flatMap(d=>[{x:d.x,z:d.z,hx:d.width/2,hz:d.depth/2},{x:d.x,z:d.chairZ,hx:.55,hz:.39}]);
export const SCHOOL_CHAIRS=Object.values(SCHOOL_DESKS).flat().map(d=>({id:`${d.roomId}.student-chair.${d.i}`,roomId:d.roomId,x:d.x,z:d.chairZ,at:{x:d.x-Math.sign(d.x)*1.35,z:d.chairZ-.22},anchor:{x:d.x,z:d.chairZ-.22,yaw:Math.PI},seatTop:.64}));
export function buildSchoolFurniture(id,{root,box,cylinder}){for(const d of SCHOOL_DESKS[id]??[]){const g=new THREE.Group();g.name=d.id;root.add(g);box(d.width,.14,d.depth,'#d5b383',d.x,1.05,d.z,.06,g);for(const dx of[-d.width/2+.15,d.width/2-.15])for(const dz of[-d.depth/2+.13,d.depth/2-.13])box(.11,.96,.11,'#91a899',d.x+dx,.50,d.z+dz,.025,g);const c=new THREE.Group();c.name=`${id}.student-chair.${d.i}`;root.add(c);box(1.1,.14,.74,id==='art'?'#c1ae87':'#9cb7a3',d.x,.57,d.chairZ,.06,c);box(1.1,.55,.12,id==='art'?'#cbb995':'#a7c1ac',d.x,.99,d.chairZ+.31,.055,c);for(const dx of[-.40,.40])for(const dz of[-.25,.25])box(.085,.5,.085,'#a28c6e',d.x+dx,.27,d.chairZ+dz,.015,c);
 if(id==='art'){box(.92,.015,.64,'#fff8e7',d.x-.31,1.13,d.z,.009,g);cylinder(.14,.12,.23,'#91aeb1',d.x+.74,1.24,d.z-.23,g);for(let i=0;i<3;i++)box(.034,.38,.034,['#c68170','#c2a151','#688e9c'][i],d.x+.67+i*.06,1.43,d.z-.23,.005,g);for(let i=0;i<3;i++)box(.17,.027,.11,['#d09174','#bdc889','#97b7c6'][i],d.x-.59+i*.21,1.153,d.z-.12,.04,g);}else{box(.67,.045,.49,'#638776',d.x-.15,1.15,d.z,.02,g);box(.59,.015,.43,'#f9f1d9',d.x-.15,1.184,d.z,.01,g);const pencil=box(.41,.027,.027,'#d3ad58',d.x+.47,1.145,d.z+.17,.006,g);pencil.rotation.y=.25;}}
}
